import { describe, expect, it } from 'vitest'
import { npComplexArray, npFloatArray, npFloatMatrix, npRound, npScalar } from '../../../src/lessons/eigenvectors/numpyText'
import { eigenCode, eigenOutput, pcaCode, pcaOutput } from '../../../src/lessons/eigenvectors/snippets'
import { makeCloud, pca2 } from '../../../src/linalg/eigen'
import type { Mat2, Vec2 } from '../../../src/linalg'
import fixture from './numpy-fixture.json'

/**
 * numpy-fixture.json holds what real NumPy 2 printed for the exact code this
 * lesson shows, over a few thousand matrices and point clouds (generated by
 * running that code in Python).
 */
type EigRow = [number, number, number, number, string]
type Cloud = { points: Vec2[]; C: string; vals: string; raw: [number, number] }

const toMat = (r: readonly (number | string)[]): Mat2 => [
  [r[0] as number, r[1] as number],
  [r[2] as number, r[3] as number],
]

describe('NumPy print mimic', () => {
  it('rounds half to even like np.round', () => {
    expect(npRound(0.125, 2)).toBe(0.12)
    expect(npRound(0.375, 2)).toBe(0.38)
    expect(npRound(2.5, 0)).toBe(2)
    expect(Object.is(npRound(-0.001, 2), -0)).toBe(true)
  })

  it('prints float arrays, padding to line up the points', () => {
    expect(npFloatArray([3, 1])).toBe('[3. 1.]')
    expect(npFloatArray([2.12, 0.5])).toBe('[2.12 0.5 ]')
    expect(npFloatArray([-0, 3])).toBe('[-0.  3.]')
    expect(npFloatArray([0.01, 12])).toBe('[1.0e-02 1.2e+01]')
    expect(npFloatMatrix([[1.23, -0.45], [-0.45, 0.8]])).toBe('[[ 1.23 -0.45]\n [-0.45  0.8 ]]')
  })

  it('prints complex arrays', () => {
    expect(npComplexArray([1.5, 1.5], [2, -2])).toBe('[1.5+2.j 1.5-2.j]')
    expect(npComplexArray([3.2, -3.25], [-0.5, 12.5])).toBe('[ 3.2  -0.5j -3.25+12.5j]')
  })

  it('prints scalars like Python', () => {
    expect(npScalar(2)).toBe('2.0')
    expect(npScalar(12.3)).toBe('12.3')
  })
})

describe('eigenvalue snippet matches real NumPy', () => {
  const rows = fixture.eig as EigRow[]
  it(`agrees on all ${rows.length} matrices`, () => {
    const wrong = rows.filter((r) => eigenOutput(toMat(r)) !== r[4])
    expect(wrong.slice(0, 5).map((r) => [r, eigenOutput(toMat(r))])).toEqual([])
  })

  it('switches to the complex square root only when it has to', () => {
    expect(eigenCode([[0, -1], [1, 0]])).toContain('np.sqrt(disc + 0j)')
    expect(eigenCode([[2, 1], [1, 2]])).not.toContain('0j')
  })
})

describe('PCA snippet matches real NumPy', () => {
  const clouds = fixture.pca as Cloud[]
  it(`covariance matrix agrees on all ${clouds.length} clouds`, () => {
    const wrong = clouds.filter((c) => pcaOutput(c.points, [0, 0]).split('\n').slice(0, 2).join('\n') !== c.C)
    expect(wrong.length).toBe(0)
  })

  it('eigenvalues of the covariance agree (ours vs np.linalg.eigh)', () => {
    const wrong = clouds.filter((c) => {
      const { components } = pca2(c.points)
      const out = pcaOutput(c.points, [components[1].value, components[0].value])
      return out.split('\n')[2] !== c.vals
    })
    expect(wrong.map((c) => [c.vals, pca2(c.points).components.map((p) => p.value)])).toEqual([])
  })

  it('writes the generated cloud as a NumPy literal, three points a line', () => {
    const code = pcaCode(makeCloud(1))
    expect(code.split('\n').filter((l) => l.includes('[')).length).toBeGreaterThanOrEqual(4)
    expect(code).toContain('Xc.T @ Xc / (len(X) - 1)')
  })
})
